<?php
namespace App\Http\Controllers;
use App\Models\{Incident,IncidentEvent,User,OrganizationalUnit};
use App\Support\{Access,Audit};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class IncidentController extends Controller {
 public function index(Request $r){$v=$r->validate(['status'=>'nullable|in:new,acknowledged,investigating,in_progress,monitoring,resolved,closed','severity'=>'nullable|in:info,low,medium,high,critical']);$q=Incident::with(['unit','assignedTo'])->where(fn($q)=>config('noc.mode')==='demo'?$q->whereIn('source',['demo','manual']):$q->where('source','!=','demo'));Access::scope($q);foreach(['status','severity'] as $k)if(!empty($v[$k]))$q->where($k,$v[$k]);$incidents=$q->latest()->paginate(20)->withQueryString();$units=OrganizationalUnit::whereIn('id',$r->user()->unitIds())->orderBy('name')->get();return view('incidents',compact('incidents','units'));}
 public function show(Incident $incident){Access::assertUnit($incident->organizational_unit_id);$incident->load(['unit','assignedTo','comments.author','events','alerts']);$people=User::where('active',true)->whereHas('role',fn($q)=>$q->whereIn('slug',['superadmin','ti','noc','soc']))->orderBy('name')->get()->filter(fn($u)=>$u->isSuperAdmin()||$u->canAccessUnit($incident->organizational_unit_id));return view('incident-detail',compact('incident','people'));}
 public function store(Request $r){$v=$r->validate(['organizational_unit_id'=>'required|integer|exists:organizational_units,id','title'=>'required|string|max:160','description'=>'nullable|string|max:5000','severity'=>'required|in:info,low,medium,high,critical']);Access::assertUnit((int)$v['organizational_unit_id']);$incident=DB::transaction(function()use($v){$inc=Incident::create($v+['reference'=>'INC-'.strtoupper(substr(bin2hex(random_bytes(8)),0,10)),'status'=>'new','source'=>'manual']);$inc->events()->create(['kind'=>'created','description'=>'Incidente registrado manualmente','user_id'=>auth()->id(),'created_at'=>now()]);Audit::record('incidents.create',$inc);return $inc;});return redirect()->route('incidents.show',$incident)->with('success','Incidente criado.');}
 public function status(Request $r,Incident $incident){Access::assertUnit($incident->organizational_unit_id);$v=$r->validate(['status'=>'required|in:acknowledged,investigating,in_progress,monitoring,resolved,closed','root_cause'=>'nullable|string|max:4000']);$new=$v['status'];if($new==='closed'&&!in_array($incident->status,['resolved','closed']))return back()->withErrors(['status'=>'Resolva o incidente antes de encerrá-lo.']);DB::transaction(function()use($incident,$v,$new){$previous=$incident->status;$updates=['status'=>$new];if($new==='acknowledged'&&!$incident->acknowledged_at)$updates['acknowledged_at']=now();if(in_array($new,['resolved','closed']))$updates['resolved_at']=$incident->resolved_at??now();if(isset($v['root_cause']))$updates['root_cause']=$v['root_cause'];$incident->update($updates);$incident->events()->create(['kind'=>'status','description'=>$previous.' → '.$new,'user_id'=>auth()->id(),'created_at'=>now()]);Audit::record('incidents.status',$incident,['from'=>$previous,'to'=>$new]);});return back()->with('success','Incidente atualizado.');}
 public function assign(Request $r,Incident $incident){Access::assertUnit($incident->organizational_unit_id);$v=$r->validate(['assigned_to'=>'required|integer|exists:users,id']);$who=User::findOrFail($v['assigned_to']);abort_unless($who->active && ($who->isSuperAdmin()||$who->canAccessUnit($incident->organizational_unit_id)) && $who->hasPermission('incidents.manage'),422,'Responsável não autorizado.');DB::transaction(function()use($incident,$who){$incident->update(['assigned_to'=>$who->id]);DB::table('incident_assignments')->insert(['incident_id'=>$incident->id,'user_id'=>$who->id,'assigned_by'=>auth()->id(),'created_at'=>now()]);$incident->events()->create(['kind'=>'assignment','description'=>'Atribuído a '.$who->name,'user_id'=>auth()->id(),'created_at'=>now()]);Audit::record('incidents.assign',$incident,['to_user'=>$who->id]);});return back()->with('success','Responsável atualizado.');}
 public function comment(Request $r,Incident $incident){Access::assertUnit($incident->organizational_unit_id);$v=$r->validate(['body'=>'required|string|max:3000']);$incident->comments()->create(['body'=>$v['body'],'user_id'=>auth()->id()]);Audit::record('incidents.comment',$incident);return back()->with('success','Comentário adicionado.');}
}
